CREATE SCHEMA app;

CREATE TABLE app.accounts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL
);

CREATE TABLE app.audit_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id bigint NOT NULL,
  event_name text NOT NULL
);

ALTER TABLE app.accounts ENABLE ROW LEVEL SECURITY;

CREATE POLICY accounts_select ON app.accounts
  FOR SELECT
  TO public
  USING (name IS NOT NULL);

CREATE INDEX accounts_name_idx ON app.accounts (name);

CREATE OR REPLACE FUNCTION app.greeting()
RETURNS text
LANGUAGE sql
STABLE
AS $$
  SELECT 'hi'::text
$$;

CREATE VIEW app.account_names AS
SELECT upper(name) AS name FROM app.accounts;

COMMENT ON TABLE app.accounts IS 'Customer accounts';
